import 'package:flutter/foundation.dart';

/// Defines the role of a message sender in the AI Coach conversation architecture.
enum CoachRole {
  system,
  user,
  assistant;

  String toJson() => name;

  static CoachRole fromJson(String json) {
    return CoachRole.values.firstWhere(
      (e) => e.name == json,
      orElse: () => CoachRole.assistant,
    );
  }
}

/// Where an assistant message came from, stored in [CoachMessage.category].
/// Only [ai] is a real model answer.
class CoachReplySource {
  CoachReplySource._();

  /// Generated by the model through the ai-proxy (or a cached model answer).
  static const String ai = 'ai';

  /// Produced on the device without calling the model: a redirect for an
  /// unrelated request, or an answer read straight from the user's own data.
  static const String local = 'local';

  /// A failure notice (timeout, connection, quota...), not an answer.
  static const String error = 'error';
}

/// Represents a single message exchange in the AI Coach chat architecture.
@immutable
class CoachMessage {
  final String id;
  final CoachRole role;
  final String content;
  final DateTime timestamp;
  final String? category;
  final Map<String, dynamic>? contextSnapshot;
  final String? imagePath;
  final String? imageBase64;
  final String? imageMimeType;

  const CoachMessage({
    required this.id,
    required this.role,
    required this.content,
    required this.timestamp,
    this.category,
    this.contextSnapshot,
    this.imagePath,
    this.imageBase64,
    this.imageMimeType,
  });

  /// Whether this message includes an attached image.
  bool get hasImage =>
      (imagePath != null && imagePath!.isNotEmpty) ||
      (imageBase64 != null && imageBase64!.isNotEmpty);

  CoachMessage copyWith({
    String? id,
    CoachRole? role,
    String? content,
    DateTime? timestamp,
    String? category,
    Map<String, dynamic>? contextSnapshot,
    String? imagePath,
    String? imageBase64,
    String? imageMimeType,
  }) {
    return CoachMessage(
      id: id ?? this.id,
      role: role ?? this.role,
      content: content ?? this.content,
      timestamp: timestamp ?? this.timestamp,
      category: category ?? this.category,
      contextSnapshot: contextSnapshot ?? this.contextSnapshot,
      imagePath: imagePath ?? this.imagePath,
      imageBase64: imageBase64 ?? this.imageBase64,
      imageMimeType: imageMimeType ?? this.imageMimeType,
    );
  }

  factory CoachMessage.fromJson(Map<String, dynamic> json) {
    return CoachMessage(
      id: json['id'] as String? ?? '',
      role: CoachRole.fromJson(json['role'] as String? ?? 'assistant'),
      content: json['content'] as String? ?? '',
      timestamp: json['timestamp'] != null
          ? DateTime.parse(json['timestamp'].toString())
          : DateTime.now(),
      category: json['category'] as String?,
      contextSnapshot: json['contextSnapshot'] != null
          ? Map<String, dynamic>.from(json['contextSnapshot'] as Map)
          : null,
      imagePath: json['imagePath'] as String?,
      imageBase64: json['imageBase64'] as String?,
      imageMimeType: json['imageMimeType'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'role': role.toJson(),
    'content': content,
    'timestamp': timestamp.toIso8601String(),
    if (category != null) 'category': category,
    if (contextSnapshot != null) 'contextSnapshot': contextSnapshot,
    if (imagePath != null) 'imagePath': imagePath,
    if (imageBase64 != null) 'imageBase64': imageBase64,
    if (imageMimeType != null) 'imageMimeType': imageMimeType,
  };

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoachMessage &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          role == other.role &&
          content == other.content &&
          timestamp == other.timestamp &&
          category == other.category &&
          imagePath == other.imagePath &&
          imageBase64 == other.imageBase64 &&
          imageMimeType == other.imageMimeType;

  @override
  int get hashCode =>
      id.hashCode ^
      role.hashCode ^
      content.hashCode ^
      timestamp.hashCode ^
      category.hashCode ^
      imagePath.hashCode ^
      imageBase64.hashCode ^
      imageMimeType.hashCode;
}
